import 'dart:async';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/pregnancy_service.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'pregnancy_event.dart';import 'pregnancy_state.dart';class PregnancyBloc extends Bloc<PregnancyEvent,PregnancyState>{final PregnancyService service;PregnancyBloc({PregnancyService?service}):service=service??PregnancyService(),super(const PregnancyState()){on<PregnancyStarted>(_load);on<PregnancyRefreshed>(_load);on<PregnancyFilterBySpecialty>(_filter);on<PregnancySearch>(_search);on<PregnancyUpdateTracker>(_update);}Future<void>_load(PregnancyEvent e,Emitter<PregnancyState>emit)async{emit(state.copyWith(isLoading:true,errorMessage:null));try{final u=FirebaseAuth.instance.currentUser?.uid;final r=await Future.wait([service.getTopDoctors(limit:20),service.streamClinics(limit:20).first,service.streamTips(limit:20).first,service.streamHospitals(limit:10)]);final t=u==null?null:await service.getTracker(u);emit(state.copyWith(isLoading:false,doctors:r[0]as List<PregnancyDoctor>,clinics:r[1]as List<PregnancyClinic>,tips:r[2]as List<PregnancyTip>,hospitals:r[3]as List<PregnancyHospital>,tracker:t));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}Future<void>_filter(PregnancyFilterBySpecialty e,Emitter<PregnancyState>emit)async{emit(state.copyWith(isLoading:true,selectedSpecialty:e.specialty));try{emit(state.copyWith(isLoading:false,doctors:await service.streamDoctors(specialty:e.specialty).first));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}void _search(PregnancySearch e,Emitter<PregnancyState>emit){final q=e.query.trim().toLowerCase();emit(state.copyWith(doctors:state.doctors.where((d)=>d.name.toLowerCase().contains(q)||d.specialty.toLowerCase().contains(q)).toList()));}Future<void>_update(PregnancyUpdateTracker e,Emitter<PregnancyState>emit)async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return;try{await service.updateTracker(uid,e.data);emit(state.copyWith(tracker:await service.getTracker(uid)));}catch(x){emit(state.copyWith(errorMessage:x.toString()));}}}
